-- Compact guidance and latest explicit feedback; no new tables or full article copies.
alter table public.library_materials add column if not exists guidance jsonb;
alter table public.user_library_profiles add column if not exists material_feedback jsonb not null default '{}'::jsonb;
-- Correct the original generic annotation without overwriting later editorial changes.
update public.library_materials
set short_description = 'Выбирайте товар по своим критериям: AI поможет разобрать отзывы, выделить повторяющиеся плюсы, недостатки и риски перед покупкой.'
where slug = '300-otzyvov-za-5-minut'
  and short_description = 'Показывает, как быстро собрать массив отзывов и вытащить из них повторяющиеся боли, желания и идеи для решений с помощью AI.';
-- Reviewed summaries of the original Telegraph articles. Existing editorial guidance is preserved.
update public.library_materials set guidance = '{"when_to_use": "Когда дел и мыслей много, а выбрать первый шаг сложно.", "outcome": "Три приоритета на ближайшие сутки и маленькое действие, с которого можно начать.", "steps": ["Выгрузи мысли голосом или текстом без предварительной сортировки.", "Попроси AI выделить задачи, ожидания и решения, затем выбрать три приоритета.", "Проверь, что AI ничего не придумал, и выполни один небольшой первый шаг."]}'::jsonb where slug = 'vygruzi-golovu-za-7-min' and guidance is null;
update public.library_materials set guidance = '{"when_to_use": "Когда выбираешь товар и хочешь разобраться в большом количестве отзывов.", "outcome": "Плюсы, повторяющиеся недостатки и риски товара с учётом твоих требований к покупке.", "steps": ["Опиши, для чего нужен товар и какие свойства важны именно тебе.", "Передай AI тексты или файл с отзывами; одна ссылка не гарантирует доступа к ним.", "Сопоставь повторяющиеся плюсы и недостатки со своими критериями, отдельно проверь серьёзные риски."]}'::jsonb where slug = '300-otzyvov-za-5-minut' and guidance is null;
update public.library_materials set guidance = '{"when_to_use": "Когда после созвонов теряются решения, обещания и ответственность.", "outcome": "Единый реестр договорённостей: действие, ответственный, срок, источник и блокер.", "steps": ["Собери расшифровки рабочих встреч за неделю.", "Попроси AI извлечь обязательства и указать, где нет ответственного или срока, без догадок.", "Проверь спорные решения по исходным разговорам и подготовь вопросы команде."]}'::jsonb where slug = 'chto-komanda-poobeshchala-i-zabyla' and guidance is null;
update public.library_materials set guidance = '{"when_to_use": "Когда нужен узнаваемый визуальный стиль для серии публикаций или рекламы.", "outcome": "Продуманная визуальная система вместо набора несвязанных AI-картинок.", "steps": ["Опиши аудиторию, задачу и формат серии, попроси AI выступить арт-директором.", "До генерации согласуй концепцию, композицию, палитру, типографику и общие элементы.", "Проверь, что изображения работают как единая серия и соответствуют исходной задаче."]}'::jsonb where slug = 'kak-delat-ai-dizajn-kotoryj-ne-vyglyadit-kak-ai' and guidance is null;
update public.library_materials set guidance = '{"when_to_use": "Когда заявки уже есть, но часть клиентов пропадает до покупки.", "outcome": "Повторяющиеся утечки продаж и конкретные гипотезы для проверки на следующих диалогах.", "steps": ["Собери потерянные переписки или расшифровки разговоров с клиентами.", "Найди повторяющиеся разрывы: забытый follow-up, отсутствие следующего шага или слабое выяснение задачи.", "Проверь выводы по исходным диалогам и выбери конкретное изменение для следующих продаж."]}'::jsonb where slug = 'vozmozhno-vam-ne-nuzhny-novye-lidy' and guidance is null;
update public.library_materials set guidance = '{"when_to_use": "Когда выбираешь между вариантами, но факты перемешались со страхами.", "outcome": "Карта решения: важные критерии, компромиссы, неизвестное и один проверочный шаг.", "steps": ["Опиши ситуацию и отдели подтверждённые факты от предположений и страхов.", "Сравни варианты по своим критериям и обозначь цену каждого выбора.", "Выбери небольшой тест, который уменьшит неопределённость; окончательное решение остаётся за тобой."]}'::jsonb where slug = 'ne-mozhesh-prinyat-reshenie-vot-proverennyj-sposob' and guidance is null;
